import{_ as t,o as s,c as e,ag as n}from"./chunks/framework.C5oN-8Wt.js";const r="/cns_master_docs/teaching-v0.2.0-alpha/04-signal-views.svg",o="/cns_master_docs/teaching-v0.2.0-alpha/04-signal-views-waterfall.svg",m=JSON.parse('{"title":"04 同一信号的时域、频谱与瀑布","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/learn/04-signal-views/index.md","filePath":"v0.2.0-alpha/learn/04-signal-views/index.md"}'),d={name:"v0.2.0-alpha/learn/04-signal-views/index.md"};function i(l,a,h,p,c,g){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="_04-同一信号的时域、频谱与瀑布" tabindex="-1">04 同一信号的时域、频谱与瀑布 <a class="header-anchor" href="#_04-同一信号的时域、频谱与瀑布" aria-label="Permalink to &quot;04 同一信号的时域、频谱与瀑布&quot;">​</a></h1><p>适用 <strong>v0.2.0-alpha</strong>。前置：<a href="./../02-wave-quantities/">频率、幅度</a>与<a href="./../03-sampling/">采样</a>。本课不要求会傅里叶推导。</p><h2 id="低空应用问题与学习目标" tabindex="-1">低空应用问题与学习目标 <a class="header-anchor" href="#低空应用问题与学习目标" aria-label="Permalink to &quot;低空应用问题与学习目标&quot;">​</a></h2><p>地面接收的波形可能同时包含多种快慢的变化。时域图复杂时，怎样找出它包含哪些频率？本课把两个已知频率相加，再用三种视图看<strong>同一个加法器输出</strong>，学会说明每张图回答什么问题。</p><p>时域看数值随时间怎样变化；频域看一段样本中不同频率成分的大小；瀑布把连续多帧频谱按时间排起来，看频率成分何时出现或改变。“FFT”是计算频谱的一种快速算法名，先理解输出坐标即可。</p><h2 id="接线与参数理由" tabindex="-1">接线与参数理由 <a class="header-anchor" href="#接线与参数理由" aria-label="Permalink to &quot;接线与参数理由&quot;">​</a></h2><p><a href="../../../downloads/teaching-v0.2.0-alpha/04-signal-views.cnsproj" download>下载 04-signal-views.cnsproj</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1：64 Hz、幅度 1 ──→ 加法器 in1</span></span>
<span class="line"><span>信号源 2：256 Hz、幅度 0.5 → 加法器 in2</span></span>
<span class="line"><span>                            out ──→ 时域观察器</span></span>
<span class="line"><span>                                ├─→ 频谱观察器</span></span>
<span class="line"><span>                                └─→ 瀑布观察器</span></span></code></pre></div><p>两源均为正弦、相位 0、偏置 0、Fs=<strong>1024 sample/s</strong>。加法器有两输入，同速同类型逐样本相加。工程频谱为 <strong>N=1024、周期 Hann、0% 重叠</strong>，因此频点间隔 <code>Fs/N=1 Hz</code>，每帧覆盖 <strong>1 s</strong>，相邻帧也隔 <strong>1 s</strong>。本例频率落在整数频点，便于读数。</p><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>打开工程，在各观察器“参数”页确认来源都是<strong>加法器输出</strong>。时域选 <code>out</code>；频谱与瀑布选同节点的频谱来源。瀑布模式在只有一路频谱捕获时选择，多路模式的限制不代表不能运行。</li><li>先设每路 <strong>4096</strong> 样本，F5。完成后把时域横轴缩到约 <strong>0.0625 s</strong>，观察慢起伏上叠加较快的变化。</li><li>在频谱中读横轴 Hz、纵轴线性峰值幅度。找约 64 Hz 和 256 Hz 的两个主峰，并记录各自高度。</li><li>为看瀑布持续更新，先停止，设每路样本数 <strong>0</strong>，再运行。等至少数帧，看同一频率位置是否持续出现条带，再 Shift+F5 停止。</li><li>做单参数练习后，把工程另存；不同运行的瀑布会在新准备时重建，不把它当作长期记录文件。</li></ol><h2 id="预期图像及解释" tabindex="-1">预期图像及解释 <a class="header-anchor" href="#预期图像及解释" aria-label="Permalink to &quot;预期图像及解释&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.2.0-alpha/04-signal-views.svg"><img src="`+r+'" alt="实际 GNU 数据：双音的时域变化与 64、256 Hz 频谱峰"></a></p><p><a href="/cns_master_docs/teaching-v0.2.0-alpha/04-signal-views-waterfall.svg"><img src="'+o+'" alt="由两帧实际 GNU 频谱生成的参考瀑布，频率 64 和 256 Hz 位置持续有较强幅度"></a></p><p>参考瀑布来自验证时每路 2048 样本的两帧实际频谱，时间按窗口起点标注，颜色标度以幅度 1 为参考。课堂用 4096 样本会得到四帧，连续运行会继续增加帧；这张图不是循环播放的动画，也不是 Master 界面截图。</p><table tabindex="0"><thead><tr><th>视图</th><th>输入、坐标和预期</th></tr></thead><tbody><tr><td>时域</td><td>加法器 <code>out</code>；横轴 s、纵轴归一化幅度。曲线为两路之和，不再是单一正弦；峰值不一定恰好等于两个幅度相加。</td></tr><tr><td>频谱</td><td>加法器同一路的完整 FFT 帧；横轴 0—512 Hz，纵轴线性峰值幅度。64 Hz 主峰约 1，256 Hz 主峰约 0.5。周期 Hann 会使主峰邻近频点也有能量，不把每个相邻频点都叫作新信号。</td></tr><tr><td>瀑布</td><td>相同来源的连续频谱；频率与时间分别沿标注的两轴，颜色表示相对参考幅度的 dB。固定双音在对应频率形成持续条带，0.5 幅度的条带通常较暗。读实际刻度和色标，不用颜色猜绝对瓦数。</td></tr></tbody></table><p>“线性峰值幅度”与功率不同。幅度 0.5 相对幅度 1 的比值为 1/2；按 <code>20×log10(0.5)</code> 为约 <strong>−6.02 dB</strong>。这里 dB 表示相对比值，不是 dBm，不能直接称作接收功率。</p><h2 id="单参数对照" tabindex="-1">单参数对照 <a class="header-anchor" href="#单参数对照" aria-label="Permalink to &quot;单参数对照&quot;">​</a></h2><p>停止，只将信号源 2 的频率从 <strong>256 改为 128 Hz</strong>，其他参数不动，再运行。预测：64 Hz 的峰是否移动？应保留 64 Hz 主峰，第二个主峰移到 128 Hz、幅度仍约 0.5；瀑布在新运行中显示 64 与 128 Hz 两条带。时域中的快起伏随之变慢。</p><p>若希望在<strong>同一次</strong>连续瀑布中观察条带拐到新频率，可在源属性使用已支持的在线应用，并核对该节点实际回执。修改前后的帧可能跨越切换，不能将回执时刻宣称为精确样本边界。本课的必做对照使用停止重跑，避免误读旧缓存。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>解释与处理</th></tr></thead><tbody><tr><td>时域看起来像乱线</td><td>先缩小到几个周期，核对是否仍选加法器的时域输出。</td></tr><tr><td>只看到一个峰</td><td>放大频谱范围，检查源 2 幅度和加法器两条连线，不要改相位来找峰。</td></tr><tr><td>瀑布只有几行／更新不快</td><td>本配置每帧相隔 1 s 样本时间；有限 4096 点只有 4 帧，不靠提高窗口刷新率增加频谱帧。</td></tr><tr><td>改 FFT 窗后峰形变了</td><td>观察设置改变了频谱估计，不代表时域源被滤波。</td></tr><tr><td>瀑布像连续画面，是否是动画？</td><td>每条新频谱来自 worker 的实际窗口计算；没有收到新帧时不能推断产生了新数据。</td></tr></tbody></table><p><a href="./../../modules/signal_source/">信号源</a> · <a href="./../../modules/add/">加法器</a> · <a href="./../../#设置整个工程的频谱">工程频谱设置</a> · <a href="./../">返回学习路径</a> · <a href="./../05-noise/">下一课：噪声 →</a></p>',23)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
